761:static int xsk_skb_metadata(struct sk_buff *skb, void *buffer,
762:			    struct xdp_desc *desc, struct xsk_buff_pool *pool,
763:			    u32 hr)
764:{
765:	struct xsk_tx_metadata *meta = NULL;
766:
767:	if (unlikely(pool->tx_metadata_len == 0))
768:		return -EINVAL;
769:
770:	meta = buffer - pool->tx_metadata_len;
771:	if (unlikely(!xsk_buff_valid_tx_metadata(meta)))
772:		return -EINVAL;
773:
774:	if (meta->flags & XDP_TXMD_FLAGS_CHECKSUM) {
775:		if (unlikely(meta->request.csum_start +
776:			     meta->request.csum_offset +
777:			     sizeof(__sum16) > desc->len))
778:			return -EINVAL;
779:
780:		skb->csum_start = hr + meta->request.csum_start;
781:		skb->csum_offset = meta->request.csum_offset;
782:		skb->ip_summed = CHECKSUM_PARTIAL;
783:
784:		if (unlikely(pool->tx_sw_csum)) {
785:			int err;
786:
787:			err = skb_checksum_help(skb);
788:			if (err)
789:				return err;
790:		}
791:	}
792:
793:	if (meta->flags & XDP_TXMD_FLAGS_LAUNCH_TIME)
794:		skb->skb_mstamp_ns = meta->request.launch_time;
795:	xsk_tx_metadata_to_compl(meta, &skb_shinfo(skb)->xsk_meta);
796:
797:	return 0;
798:}
